def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    with np.errstate(divide='ignore', invalid='ignore'):
        remaining = bins - item
        valid = (remaining >= 0) & (bins > 0)
        score = np.exp(-np.abs(remaining - item))
        return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    with np.errstate(divide='ignore', invalid='ignore'):
        ratio = item / bins
        valid = (bins >= item) & (bins > 0)
        score = np.where(ratio <= 0.5, ratio, 1.0 - ratio)
        return np.where(valid, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)
